#!/bin/zsh
# H5 seat driver (D4 pass 5). One stage per call; every log's first and last line carry the wall clock and the 1/5/15-min
# load. Every build, unit run and browser run goes through the machine guard; every run that may start Playwright WebKit
# also holds the machine-wide WebKit lock (guarded --exclusive webkit), the whole WebKit stage in one hold. Browser runs
# never take --light. Serial: one heavy run at a time. Do not edit this file while a stage runs.
#   run-h5.sh route <dp|f>          the worktree's src at HEAD + floor v3 + that route's pass-4 patch (reverse-applies the other)
#   run-h5.sh build <dp|f>          <tag>-src (the pass-5 route dir), <tag>-atk-src and <tag>-atk-src-dev (the attack route)
#   run-h5.sh reads <dp|f> <chromium|webkit>   the H5 cells on the library: CANON (clean, 7 plants, 2 controls), FACT, ATTACK, REPORT
#   run-h5.sh selftest <chromium|webkit> [--only ..]   the whole self-test (or part) under one hash
#   run-h5.sh unit                  unit.mjs's own self-test on the worktree
# The worktree and bulky outputs live in .claude/worktrees/bl/D4/p5/h5 (scratch); the logs H5.md cites live in logs/.
W=/Users/mkbabb/Programming/glass-ui/.claude/worktrees/bl/D4/p5/h5
WT=$W/wt; O=$W/out; B=$O/builds
T=/Users/mkbabb/Programming/glass-ui/docs/tranches/BL/design/tile
HN=$T/harness; P4=$T/pass-4; R5=$T/pass-5/H5/routes; L=$T/pass-5/H5/logs
G=~/.claude/guard/guarded
mkdir -p $L $O
stamp() { echo "$(date '+%F %T') · load $(sysctl -n vm.loadavg)"; }
glog() { # glog <name> [guard opts] -- <cmd>
  local name=$1; shift; local gopts=(); while [[ $1 != -- ]]; do gopts+=($1); shift; done; shift
  local F=$L/$name.log; stamp > $F
  $G --rss-gb 8 $gopts -- zsh -c 'echo "admitted · $(date "+%F %T") · load $(sysctl -n vm.loadavg)"; exec "$@"' _ "$@" >> $F 2>&1
  local rc=$?; echo "exit $rc · $(stamp)" >> $F; return $rc
}
patchOf() { [[ $1 == dp ]] && echo $P4/D4-Dp-proto.patch || echo $P4/D4-F-proto.patch; }
routeOf() { [[ $1 == dp ]] && echo $R5/D4-Dp || echo $R5/D4-F; }

case $1 in
  route)
    F=$L/route-$2.log; stamp > $F
    { cd $WT
      for x in dp f; do git apply --check -R $(patchOf $x) 2>/dev/null && git apply -R $(patchOf $x) && echo "reverse-applied $x"; done
      git apply --check -R $P4/floor-v3.patch 2>/dev/null || { git apply $P4/floor-v3.patch && echo "applied floor v3"; }
      git apply $(patchOf $2) && echo "applied $2 ($(shasum $(patchOf $2) | cut -c1-8))"
      echo "src dirty paths: $(git status --porcelain -- src | wc -l | tr -d ' ')"; } >> $F 2>&1
    echo "exit $? · $(stamp)" >> $F ;;
  build)
    glog build-$2-src --timeout 20 -- node $HN/build.mjs $WT --label $2-src --out $O --flavor src --route $(routeOf $2)
    for f in src src-dev; do glog build-$2-atk-$f --timeout 20 -- node $HN/build.mjs $WT --label $2-atk-$f --out $O --flavor $f --route $HN/attack-route; done ;;
  reads)
    x=$2; e=$3; ex=(); [[ $e == webkit ]] && ex=(--exclusive webkit)
    glog reads-$x-$e $ex --timeout 90 -- zsh -c "
      set -x
      node $HN/canon.mjs --build $B/$x-src --out $O --engine $e
      for p in a s h layer foreign unlayered cq lowlayer cqoff; do node $HN/canon.mjs --build $B/$x-src --out $O/plant-\$p --engine $e --plant \$p; done
      node $HN/fact-split.mjs --build $B/$x-atk-src --out $O --engine $e
      node $HN/fact-split.mjs --build $B/$x-atk-src-dev --out $O --engine $e
      node $HN/attack.mjs --build $B/$x-atk-src-dev --out $O --engine $e
      node $HN/report-h46.mjs --build $B/$x-src --out $O --engine $e
      node $HN/report-h46.mjs --build $B/$x-atk-src --out $O/refuse --engine $e
      true" ;;
  stub)
    # harness validity only, NOT floor v4: the M-13 bounded pin appended to the D′ worktree's toggle-group sheet, the
    # attack builds, FACT and ATTACK on them, then the sheet restored from a copy and checked against git diff
    x=$2; e=${3:-chromium}; ex=(); [[ $e == webkit ]] && ex=(--exclusive webkit)
    SH=$WT/src/components/toggle-group/styles.css
    F=$L/stub-$x-$e.log; stamp > $F
    D0=$(cd $WT && git diff HEAD --binary | shasum | cut -c1-12); cp $SH $W/styles.css.orig
    printf '\n@layer components {\n    @scope (.toggle-group__item) to (.toggle-group) {\n        :scope,\n        :scope * {\n            --selection-tile: inherit !important;\n        }\n    }\n}\n' >> $SH
    echo "stub appended; git diff before $D0" >> $F; tail -8 $SH >> $F
    for f in src src-dev; do $G --rss-gb 8 --timeout 20 -- node $HN/build.mjs $WT --label $x-stub-atk-$f --out $O --flavor $f --route $HN/attack-route >> $F 2>&1; done
    cp $W/styles.css.orig $SH; D1=$(cd $WT && git diff HEAD --binary | shasum | cut -c1-12)
    echo "sheet restored; git diff after $D1 ($([[ $D0 == $D1 ]] && echo equal || echo DIFFERS))" >> $F
    $G --rss-gb 8 $ex --timeout 60 -- zsh -c "node $HN/fact-split.mjs --build $B/$x-stub-atk-src --out $O/stub --engine $e; node $HN/fact-split.mjs --build $B/$x-stub-atk-src-dev --out $O/stub --engine $e; node $HN/attack.mjs --build $B/$x-stub-atk-src-dev --out $O/stub --engine $e; true" >> $F 2>&1
    echo "exit $? · $(stamp)" >> $F ;;
  selftest)
    # selftest <engine> <part name> [--only ids]: one guarded call (and, for WebKit, one --exclusive webkit hold) per
    # part, each under the guard's 90-min cap. (The first Chromium call ran as `selftest chromium --only …`: its log is
    # selftest-chromium-part.log.)
    e=$2; tag=$3; shift 3; ex=(); [[ $e == webkit ]] && ex=(--exclusive webkit)
    glog selftest-$e-$tag $ex --timeout 90 -- node $HN/selftest.mjs --out $O/selftest --engines $e "$@" ;;
  webkit-reads)
    # ONE --exclusive webkit hold: the H5 cells on both routes' builds and the stub's attack builds (static builds)
    glog webkit-reads --exclusive webkit --timeout 90 -- zsh -c "
      for x in dp f; do
        node $HN/canon.mjs --build $B/\$x-src --out $O --engine webkit
        for p in a s h layer foreign unlayered cq lowlayer cqoff; do node $HN/canon.mjs --build $B/\$x-src --out $O/plant-\$p --engine webkit --plant \$p; done
        node $HN/fact-split.mjs --build $B/\$x-atk-src --out $O --engine webkit
        node $HN/fact-split.mjs --build $B/\$x-atk-src-dev --out $O --engine webkit
        node $HN/attack.mjs --build $B/\$x-atk-src-dev --out $O --engine webkit
        node $HN/report-h46.mjs --build $B/\$x-src --out $O --engine webkit
        node $HN/report-h46.mjs --build $B/\$x-atk-src --out $O/refuse --engine webkit
      done
      node $HN/fact-split.mjs --build $B/dp-stub-atk-src --out $O/stub --engine webkit
      node $HN/fact-split.mjs --build $B/dp-stub-atk-src-dev --out $O/stub --engine webkit
      node $HN/attack.mjs --build $B/dp-stub-atk-src-dev --out $O/stub --engine webkit
      true" ;;
  unit)
    glog unit-selftest --light --timeout 20 -- node $HN/unit.mjs $WT --selftest --out $O ;;
  *) echo "stages: route build reads selftest unit"; exit 2 ;;
esac
